export function validateSharedSound(item){const d=item?.data;if(item?.type!=='sound'||typeof item.id!=='string'||!/^[\w-]{1,140}$/.test(item.id)||typeof item.owner!=='string'||!/^[\w-]{1,140}$/.test(item.owner)||typeof item.name!=='string'||!item.name.trim()||item.name.length>60||d?.version!==1||!Number.isInteger(d.sampleRate)||d.sampleRate<8000||d.sampleRate>192000||!Array.isArray(d.channels)||d.channels.length<1||d.channels.length>2||!d.channels.every(c=>c instanceof Float32Array&&c.length>0&&c.length<=d.sampleRate*60&&c.length===d.channels[0].length&&c.every(n=>Number.isFinite(n))))throw Error('A shared sound is incomplete or invalid.');return item;}
export function sharedSoundRecord(id,owner,name,buffer){return validateSharedSound({id,type:'sound',owner,name,updatedAt:Date.now(),data:{version:1,sampleRate:buffer.sampleRate,channels:Array.from({length:buffer.numberOfChannels},(_,i)=>new Float32Array(buffer.getChannelData(i)))}});}
